import { existsSync } from "node:fs";
import { mkdir, unlink, writeFile } from "node:fs/promises";
import { join } from "node:path";

const BUILTIN_KEYS = new Set(["MODE", "DEV", "PROD", "SSR", "BASE_URL"]);
const STEAMBUN_DIR = ".steambun";
const LEGACY_ENV_DTS = "steambun-env.d.ts";

function isIdent(key: string): boolean {
  return /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(key);
}

function fieldLine(key: string): string {
  const name = isIdent(key) ? key : JSON.stringify(key);
  return `  readonly ${name}: string;`;
}

/** Ambient `ImportMetaEnv` for envPrefix-matched keys. Builtins live in `steambun/client`. */
export function generateEnvDts(
  publicKeys: string[],
  hasRoutesDts = false,
): string {
  const extra = [...new Set(publicKeys)]
    .filter((key) => !BUILTIN_KEYS.has(key))
    .sort()
    .map(fieldLine);

  const header = `// Generated by steambun from envPrefix-matched keys. Do not edit.
/// <reference types="steambun/client" />${hasRoutesDts ? '\n/// <reference path="./routes.d.ts" />' : ""}
`;

  if (extra.length === 0) return header;

  return `${header}
export {};

declare global {
  interface ImportMetaEnv {
${extra.map((line) => `  ${line}`).join("\n")}
  }
}
`;
}

export async function writeEnvDts(
  root: string,
  publicEnv: Record<string, string>,
): Promise<string> {
  const dir = join(root, STEAMBUN_DIR);
  await mkdir(dir, { recursive: true });
  const path = join(dir, "env.d.ts");
  const hasRoutesDts = existsSync(join(dir, "routes.d.ts"));
  await writeFile(path, generateEnvDts(Object.keys(publicEnv), hasRoutesDts));
  await removeLegacyEnvDts(root);
  return path;
}

async function removeLegacyEnvDts(root: string): Promise<void> {
  const legacy = join(root, LEGACY_ENV_DTS);
  if (!existsSync(legacy)) return;
  await unlink(legacy);
}
